import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    a, b = data[0], data[1]
    x = data[2:2 + a]
    y = data[2 + a:2 + a + b]

    j = 0
    for val in x:
        if j < b and val == y[j]:
            j += 1

    print('S' if j == b else 'N')

if __name__ == "__main__":
    main()
